<section class="container admin"><?php require __DIR__.'/_nav.php'?><h1>Media</h1><?php if($x=$_SESSION['error']??null):unset($_SESSION['error'])?><div class="alert"><?=e($x)?></div><?php endif?><form class="inline" method="post" enctype="multipart/form-data"><?=csrf_field()?><label>Gambar JPEG, PNG, atau WebP<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label><label>Alt text<input name="alt_text" required></label><button class="button">Unggah</button></form><div class="media-grid"><?php foreach($rows as $m):?><figure><img src="/uploads/<?=e($m['filename'])?>" alt="<?=e($m['alt_text'])?>" width="<?=$m['width']?>" height="<?=$m['height']?>" loading="lazy"><figcaption><?=e($m['original_name'])?></figcaption></figure><?php endforeach?></div></section>
